mapper.select:
SELECT DISTINCT a.*, ${userId} as userId FROM `sys_role_permission` b LEFT JOIN sys_permission a ON a.id = b.permission_id LEFT JOIN sys_user_role c ON b.role_id = c.role_id WHERE c.user_id = #{userId} and a.menu_type != 3
and a.parent_id = #{parentId}
and (a.parent_id = 0 or a.parent_id is null)
